fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    // Allocate a new vector with the same capacity as the input
    let mut result: Vec<char> = Vec::with_capacity(n);
    // Fill `result` by iterating over indices 0..n and
    // pushing the corresponding element from the end of `a`
    for i in 0..n {
        result.push(a[n - 1 - i]);
    }
    result
}

